async fn test_bhv_redirects_016_no_redirect_request_leaves_the_transport_default_headers_out() {
    for (no_redirect, expected) in [(true, None), (false, Some("kept".to_string()))] {
        let (base_url, head) = start_head_capture_server();
        let transport = TransportOptionsBuilder::new()
            .default_header("X-Default", "kept")
            .build()
            .expect("valid transport options");
        let client = DefaultApiClient::new(Some(transport));
        let mut headers = HashMap::new();
        headers.insert("X-Caller".to_string(), "sent".to_string());

        client
            .send_request_with_options(
                "GET",
                &format!("{}/x", base_url),
                &headers,
                None,
                &RequestOptions::new().no_redirect(no_redirect),
            )
            .await
            .expect("request succeeds");

        let head = head
            .recv_timeout(std::time::Duration::from_secs(5))
            .expect("a captured request");
        assert_eq!(
            expected,
            head_header(&head, "X-Default"),
            "no_redirect={}",
            no_redirect
        );
        assert_eq!(Some("sent".to_string()), head_header(&head, "X-Caller"));
    }
}

/// F1044: two spellings of one header are sent once, the later layer winning,
/// and a caller's lower-case Accept-Encoding suppresses the SDK's own.
#[tokio::test]
async fn test_bhv_serializationwire_036_request_headers_merge_case_insensitively() {
    let (base_url, head) = start_head_capture_server();
    let transport = TransportOptionsBuilder::new()
        .default_header("accept", "text/plain")
        .default_header("accept-encoding", "identity")
        .build()
        .expect("valid transport options");
    let client = DefaultApiClient::new(Some(transport));
    let mut headers = HashMap::new();
    headers.insert("Accept".to_string(), "application/json".to_string());

    client
        .send_request("GET", &format!("{}/test", base_url), &headers, None)
        .await
        .expect("unexpected error");

    let head = head.recv().expect("no request captured");
    let lines = |name: &str| {
        head.lines()
            .filter(|line| line.to_lowercase().starts_with(&format!("{}:", name)))
            .count()
    };
    assert_eq!(1, lines("accept"), "{}", head);
    assert_eq!(
        Some("application/json".to_string()),
        head_header(&head, "accept"),
        "{}",
        head
    );
    assert_eq!(1, lines("accept-encoding"), "{}", head);
    assert_eq!(
        Some("identity".to_string()),
        head_header(&head, "accept-encoding"),
        "{}",
        head
    );
}

