async fn test_bhv_misc_031_a_proxy_credential_is_sent_only_with_user_info() {
    let (proxy_url, with_info) = start_head_capture_server();
    let addr = proxy_url.trim_start_matches("http://").to_string();
    let transport = TransportOptionsBuilder::new()
        .proxy(&format!("http://user:pass@{}", addr))
        .build()
        .expect("valid transport options");
    let client = DefaultApiClient::new(Some(transport));
    client
        .send_request("GET", "http://api.example.com/x", &HashMap::new(), None)
        .await
        .expect("unexpected error");
    let head = with_info.recv().expect("no request captured");
    assert!(
        head_header(&head, "proxy-authorization").is_some(),
        "{}",
        head
    );

    let (proxy_url, without_info) = start_head_capture_server();
    let addr = proxy_url.trim_start_matches("http://").to_string();
    let transport = TransportOptionsBuilder::new()
        .proxy(&format!("http://{}", addr))
        .build()
        .expect("valid transport options");
    let client = DefaultApiClient::new(Some(transport));
    client
        .send_request("GET", "http://api.example.com/x", &HashMap::new(), None)
        .await
        .expect("unexpected error");
    let head = without_info.recv().expect("no request captured");
    assert_eq!(None, head_header(&head, "proxy-authorization"), "{}", head);
}

