/// Starts a server that echoes the HTTP method as JSON and includes a
/// X-Test-Header response header. Handles one request then stops.
fn start_method_echo_server() -> String {
    let listener = TcpListener::bind("127.0.0.1:0").expect("failed to bind");
    let addr = listener.local_addr().unwrap();
    let base_url = format!("http://{}", addr);

    thread::spawn(move || {
        if let Some(stream) = listener.incoming().next() {
            let mut stream = stream.unwrap();
            let mut buf = [0u8; 8192];
            let n = stream.read(&mut buf).unwrap_or(0);
            let text = String::from_utf8_lossy(&buf[..n]);

            let method = text
                .lines()
                .next()
                .and_then(|l| l.split_whitespace().next())
                .unwrap_or("GET")
                .to_string();

            let body_text = if let Some(pos) = text.find("\r\n\r\n") {
                text[pos + 4..].trim_end_matches('\0').to_string()
            } else {
                String::new()
            };

            let json_body = format!(
                r#"{{"method":"{}","body":"{}"}}"#,
                method,
                body_text.replace('"', "\\\"")
            );
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nX-Test-Header: test-value\r\nContent-Length: {}\r\n\r\n{}",
                json_body.len(),
                json_body
            );
            let _ = std::io::Write::write_all(&mut stream, response.as_bytes());
        }
    });

    thread::sleep(std::time::Duration::from_millis(50));
    base_url
}

