/* F1063: the client keeps no cookie jar, so a Set-Cookie on one response never
 * comes back as a Cookie header on the next request. */
#[tokio::test]
async fn test_bhv_retries_015_a_response_cookie_is_never_replayed() {
    let listener = TcpListener::bind("127.0.0.1:0").expect("failed to bind");
    let base_url = format!("http://{}", listener.local_addr().unwrap());
    let (tx, rx) = std::sync::mpsc::channel::<String>();
    thread::spawn(move || {
        for (index, stream) in listener.incoming().take(2).enumerate() {
            let mut stream = stream.unwrap();
            let mut buf = [0u8; 4096];
            let n = stream.read(&mut buf).unwrap_or(0);
            let _ = tx.send(String::from_utf8_lossy(&buf[..n]).to_string());
            let cookie = if index == 0 {
                "Set-Cookie: sid=abc; Path=/\r\n"
            } else {
                ""
            };
            let response = format!(
                "HTTP/1.1 200 OK\r\n{}Content-Length: 0\r\nConnection: close\r\n\r\n",
                cookie
            );
            let _ = std::io::Write::write_all(&mut stream, response.as_bytes());
        }
    });

    let client = DefaultApiClient::new(None);
    let headers = HashMap::new();
    for _ in 0..2 {
        client
            .send_request("GET", &format!("{}/session", base_url), &headers, None)
            .await
            .expect("the request must succeed");
    }

    let first = rx.recv().expect("expected the first request");
    let second = rx.recv().expect("expected the second request");
    assert!(!first.to_lowercase().contains("cookie:"), "got: {}", first);
    assert!(
        !second.to_lowercase().contains("cookie:"),
        "got: {}",
        second
    );
}

/// Gap AL: starts a server that LIES about its body encoding — it sets
/// `Content-Encoding: gzip` on the response but writes a plain, non-gzip body.
/// The client attempts to inflate the body and fails.
/// Handles one connection then stops.
fn start_content_encoding_lie_server() -> String {
    let listener = TcpListener::bind("127.0.0.1:0").expect("failed to bind");
    let addr = listener.local_addr().unwrap();
    let base_url = format!("http://{}", addr);

    thread::spawn(move || {
        if let Some(stream) = listener.incoming().next() {
            let mut stream = stream.unwrap();
            let mut buf = [0u8; 4096];
            let _ = stream.read(&mut buf);
            // Body is plain ASCII, NOT gzip — but we claim gzip encoding.
            let body = b"this is not gzip-compressed data";
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Encoding: gzip\r\nContent-Length: {}\r\n\r\n",
                body.len()
            );
            let _ = std::io::Write::write_all(&mut stream, response.as_bytes());
            let _ = std::io::Write::write_all(&mut stream, body);
        }
    });

    thread::sleep(std::time::Duration::from_millis(50));
    base_url
}

/// Gap AL (fleet-wide regression guard) — a server that mislabels its encoding
/// (declares `Content-Encoding: gzip` but sends plaintext) must surface a
/// uniform SDK error, NOT crash and NOT pass the corrupted bytes through
/// silently. The response arrived, so it is an `ApiError` carrying the real
/// status code — never a `NetworkError`.
#[tokio::test]
async fn test_bhv_transport_030_al_content_encoding_lie_surfaces_api_error() {
    let base_url = start_content_encoding_lie_server();
    let client = DefaultApiClient::new(None);
    let headers = HashMap::new();

    let err = client
        .send_request("GET", &format!("{}/lie", base_url), &headers, None)
        .await
        .expect_err("Gap AL: a Content-Encoding: gzip lie over a plaintext body must error");
    assert!(
        err.downcast_ref::<NetworkError>().is_none(),
        "Gap AL: a corrupt compressed body must not be a NetworkError, got: {}",
        err
    );
    let api_err = err
        .downcast_ref::<ApiError>()
        .unwrap_or_else(|| panic!("Gap AL: expected ApiError, got: {}", err));
    assert_eq!(
        api_err.status_code(),
        200,
        "the real status code must be kept"
    );
    assert!(
        std::error::Error::source(api_err).is_some(),
        "the decompression error must be kept as source()"
    );
    let _: &dyn OpenAPIError = api_err;
}

