/// apierror-drops-transport-cause: a transport-level failure (here a connect
/// refusal) must be wrapped in a NetworkError whose ApiError PRESERVES the
/// underlying reqwest error as its `source()`, rather than stringifying and
/// discarding it.
#[tokio::test]
async fn test_bhv_misc_282_transport_error_preserves_underlying_cause() {
    let client = DefaultApiClient::new(None);
    let headers = HashMap::new();
    // Port 1 on loopback refuses connections.
    let result = client
        .send_request("GET", "http://127.0.0.1:1/unreachable", &headers, None)
        .await;

    let err = result.expect_err("connect to a refused port must fail");
    let network_err = err
        .downcast_ref::<NetworkError>()
        .expect("transport failure must be a NetworkError");
    let _: &dyn OpenAPIError = network_err;
    let api_err = network_err.api_error();
    assert_eq!(api_err.status_code(), 0, "a transport failure has status 0");
    let source = std::error::Error::source(api_err)
        .expect("ApiError must retain the underlying transport error as source()");
    assert!(
        source.downcast_ref::<reqwest::Error>().is_some(),
        "the source must be the reqwest error, got: {}",
        source
    );
    assert!(
        matches!(
            petstore::ApiErrorKind::from(api_err.clone()),
            petstore::ApiErrorKind::Network(_)
        ),
        "a transport failure must map to ApiErrorKind::Network"
    );
}

/// network-timeout-error: a request that exceeds the configured timeout
/// surfaces as NetworkTimeoutError with status 0, keeping the reqwest error.
#[tokio::test]
async fn test_bhv_transport_058_timeout_returns_network_timeout_error() {
    let listener = TcpListener::bind("127.0.0.1:0").expect("failed to bind");
    let addr = listener.local_addr().expect("local addr");
    /* Accept the connection and never answer, so only the timeout ends it. */
    thread::spawn(move || {
        let _held: Vec<_> = listener.incoming().take(1).collect();
        thread::sleep(std::time::Duration::from_secs(5));
    });

    let transport = TransportOptionsBuilder::new()
        .timeout(Some(200))
        .build()
        .expect("valid transport options");
    let client = DefaultApiClient::new(Some(transport));
    let result = client
        .send_request(
            "GET",
            &format!("http://{}/slow", addr),
            &HashMap::new(),
            None,
        )
        .await;

    let err = result.expect_err("a request past the timeout must fail");
    let timeout_err = err
        .downcast_ref::<NetworkTimeoutError>()
        .unwrap_or_else(|| panic!("expected NetworkTimeoutError, got: {}", err));
    let _: &dyn OpenAPIError = timeout_err;
    /* A NetworkTimeoutError is a NetworkError, which is an ApiError. */
    let api_err = timeout_err.network_error().api_error();
    assert_eq!(api_err.status_code(), 0, "a timeout has status 0");
    assert!(
        std::error::Error::source(api_err).is_some(),
        "the timeout must keep the reqwest error as source()"
    );
    assert!(
        matches!(
            petstore::ApiErrorKind::from(api_err.clone()),
            petstore::ApiErrorKind::NetworkTimeout(_)
        ),
        "a timeout must map to ApiErrorKind::NetworkTimeout"
    );
}

/// The timeout is one end-to-end budget across every redirect hop: three
/// 400 ms hops and a 400 ms final answer exceed a 1000 ms budget even though
/// each single request is well inside it.
#[tokio::test]
async fn test_bhv_redirects_009_timeout_is_one_budget_across_redirect_hops() {
    let listener = TcpListener::bind("127.0.0.1:0").expect("failed to bind");
    let addr = listener.local_addr().expect("local addr");
    thread::spawn(move || {
        for (i, stream) in listener.incoming().enumerate().take(4) {
            let mut stream = stream.unwrap();
            let mut buf = [0u8; 4096];
            let _ = stream.read(&mut buf);
            thread::sleep(std::time::Duration::from_millis(400));
            let response = if i < 3 {
                "HTTP/1.1 302 Found\r\nLocation: /next\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
            } else {
                "HTTP/1.1 200 OK\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
            };
            let _ = std::io::Write::write_all(&mut stream, response.as_bytes());
        }
    });

    let transport = TransportOptionsBuilder::new()
        .timeout(Some(1000))
        .build()
        .expect("valid transport options");
    let client = DefaultApiClient::new(Some(transport));
    let err = client
        .send_request(
            "GET",
            &format!("http://{}/start", addr),
            &HashMap::new(),
            None,
        )
        .await
        .expect_err("the redirect chain must exceed the single budget");

    assert!(
        err.downcast_ref::<NetworkTimeoutError>().is_some(),
        "got: {}",
        err
    );
}

/// `timeout` is the one deadline the client arms, and reqwest applies it to
/// the whole transfer: connect, headers and body alike. A response whose
/// headers arrive inside the budget and whose body then stalls past it fails
/// at a different call site (`response.bytes()`), and it must classify as the
/// same NetworkTimeoutError rather than a bare NetworkError.
#[tokio::test]
async fn test_bhv_transport_031_body_read_timeout_returns_network_timeout_error() {
    let listener = TcpListener::bind("127.0.0.1:0").expect("failed to bind");
    let addr = listener.local_addr().expect("local addr");
    /* Headers and one body byte go out immediately, so the client is past the
     * header phase; the promised body is then never finished. */
    thread::spawn(move || {
        if let Some(Ok(mut stream)) = listener.incoming().next() {
            use std::io::{BufRead, BufReader, Write};
            /* Read the request line and headers first: a server that answers
             * without draining the request can have its write reset. */
            let mut reader = BufReader::new(stream.try_clone().expect("clone"));
            let mut line = String::new();
            while reader.read_line(&mut line).unwrap_or(0) > 0 {
                if line == "\r\n" || line == "\n" {
                    break;
                }
                line.clear();
            }
            let _ = stream.write_all(
                b"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: 1024\r\n\r\nx",
            );
            let _ = stream.flush();
            thread::sleep(std::time::Duration::from_secs(5));
        }
    });

    let transport = TransportOptionsBuilder::new()
        .timeout(Some(300))
        .build()
        .expect("valid transport options");
    let client = DefaultApiClient::new(Some(transport));
    let result = client
        .send_request(
            "GET",
            &format!("http://{}/trickle", addr),
            &HashMap::new(),
            None,
        )
        .await;

    let err = result.expect_err("a body read past the timeout must fail");
    let timeout_err = err
        .downcast_ref::<NetworkTimeoutError>()
        .unwrap_or_else(|| panic!("expected NetworkTimeoutError, got: {}", err));
    let api_err = timeout_err.network_error().api_error();
    assert_eq!(api_err.status_code(), 0, "a timeout has status 0");
}

/// Gap T6: a request issued AFTER `close()` is a wrong call order. It fails
/// fast with `ConfigurationError::InvalidState` — not an SDK error, not a
/// silent success, and not a foreign reqwest error.
#[tokio::test]
async fn test_bhv_lifecycle_023_request_after_close_returns_invalid_state() {
    let base_url = start_method_echo_server();
    let client = DefaultApiClient::new(None);
    assert!(!client.is_closed(), "client must start open");

    client.close();
    assert!(client.is_closed(), "close() must mark the client closed");

    let headers = HashMap::new();
    let err = client
        .send_request("GET", &format!("{}/echo", base_url), &headers, None)
        .await
        .expect_err("use-after-close must return an error, not succeed silently");
    match err.downcast_ref::<ConfigurationError>() {
        Some(ConfigurationError::InvalidState(reason)) => assert_eq!(
            "ApiClient has been closed and can no longer send requests", reason,
            "D29 canonical wording"
        ),
        other => panic!("expected ConfigurationError::InvalidState, got {:?}", other),
    }
}

/// A request issued after close fails with the closed-client error and never
/// reaches the transport: the listener it targets accepts no connection.
#[tokio::test]
async fn test_bhv_lifecycle_035_request_after_close_fails_and_never_reaches_the_transport() {
    let listener = TcpListener::bind("127.0.0.1:0").expect("failed to bind");
    listener
        .set_nonblocking(true)
        .expect("non-blocking listener");
    let base_url = format!("http://{}", listener.local_addr().expect("local address"));
    let client = DefaultApiClient::new(None);
    client.close();

    let err = client
        .send_request("GET", &format!("{}/echo", base_url), &HashMap::new(), None)
        .await
        .expect_err("a request after close must fail");
    assert!(matches!(
        err.downcast_ref::<ConfigurationError>(),
        Some(ConfigurationError::InvalidState(reason))
            if reason == "ApiClient has been closed and can no longer send requests"
    ));
    assert_eq!(
        std::io::ErrorKind::WouldBlock,
        listener
            .accept()
            .expect_err("no connection reached the listener")
            .kind()
    );
}

/// Starts a server that reads one request, waits `delay_ms`, and then answers 200.
fn start_delayed_server(delay_ms: u64) -> String {
    let listener = TcpListener::bind("127.0.0.1:0").expect("failed to bind");
    let addr = listener.local_addr().unwrap();
    let base_url = format!("http://{}", addr);

    thread::spawn(move || {
        if let Some(stream) = listener.incoming().next() {
            let mut stream = stream.unwrap();
            let mut buf = [0u8; 4096];
            let _ = stream.read(&mut buf);
            thread::sleep(std::time::Duration::from_millis(delay_ms));
            let response = "HTTP/1.1 200 OK\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";
            let _ = std::io::Write::write_all(&mut stream, response.as_bytes());
        }
    });

    thread::sleep(std::time::Duration::from_millis(50));
    base_url
}

/// F1078: closing is graceful. A request already in flight when `close()` runs
/// finishes, while a request started afterwards fails with the closed-client error.
#[tokio::test]
async fn test_bhv_lifecycle_019_close_lets_an_in_flight_request_finish() {
    let base_url = start_delayed_server(400);
    let client = Arc::new(DefaultApiClient::new(None));

    let in_flight = {
        let client = client.clone();
        let url = format!("{}/slow", base_url);
        tokio::spawn(async move {
            client
                .send_request("GET", &url, &HashMap::new(), None)
                .await
                .map(|r| r.status_code())
        })
    };
    tokio::time::sleep(std::time::Duration::from_millis(150)).await;
    client.close();

    let finished = in_flight.await.expect("the task must not panic");
    assert_eq!(finished.expect("the in-flight request must finish"), 200);
    let after = client
        .send_request("GET", &format!("{}/slow", base_url), &HashMap::new(), None)
        .await
        .expect_err("a request started after close must fail");
    assert!(matches!(
        after.downcast_ref::<ConfigurationError>(),
        Some(ConfigurationError::InvalidState(_))
    ));
}

/// Starts a server that reads one request and then holds the connection open
/// without answering, for at most ten seconds.
fn start_silent_server() -> String {
    let listener = TcpListener::bind("127.0.0.1:0").expect("failed to bind");
    let addr = listener.local_addr().unwrap();
    let base_url = format!("http://{}", addr);

    thread::spawn(move || {
        if let Some(stream) = listener.incoming().next() {
            let mut stream = stream.unwrap();
            let mut buf = [0u8; 4096];
            let _ = stream.read(&mut buf);
            let _ = stream.set_read_timeout(Some(std::time::Duration::from_secs(10)));
            let _ = stream.read(&mut buf);
        }
    });

    thread::sleep(std::time::Duration::from_millis(50));
    base_url
}

/// F1064: cancelling an in-flight call is dropping its future. The call stops
/// at once, without waiting for the server and without reporting a timeout, and
/// the client stays usable for the next call.
#[tokio::test]
async fn test_bhv_transport_060_dropping_an_in_flight_call_cancels_it_without_a_timeout() {
    let base_url = start_silent_server();
    let client = DefaultApiClient::new(None);

    let started = std::time::Instant::now();
    let cancelled = tokio::time::timeout(
        std::time::Duration::from_millis(300),
        client.send_request("GET", &format!("{}/slow", base_url), &HashMap::new(), None),
    )
    .await;

    assert!(
        cancelled.is_err(),
        "the unanswered call must still be pending when it is dropped"
    );
    assert!(
        started.elapsed() < std::time::Duration::from_secs(5),
        "the drop must not wait for the server"
    );
    assert!(
        !client.is_closed(),
        "cancelling a call does not close the client"
    );
    let echo_url = start_echo_server();
    let response = client
        .send_request("GET", &format!("{}/after", echo_url), &HashMap::new(), None)
        .await
        .expect("the client is usable after a cancelled call");
    assert_eq!(200, response.status_code());
}

/// Starts a server that answers `302` with a redirect to a non-HTTP URL and a body it never
/// finishes, then reports whether the client closed the connection.
fn start_unfinished_redirect_server() -> (String, std::sync::mpsc::Receiver<bool>) {
    let listener = TcpListener::bind("127.0.0.1:0").expect("failed to bind");
    let addr = listener.local_addr().unwrap();
    let (released_tx, released_rx) = std::sync::mpsc::channel();

    thread::spawn(move || {
        if let Some(stream) = listener.incoming().next() {
            let mut stream = stream.unwrap();
            let mut buf = [0u8; 4096];
            let _ = stream.read(&mut buf);
            let head = "HTTP/1.1 302 Found\r\nLocation: ftp://example.test/next\r\nContent-Length: 1000\r\n\r\npartial";
            let _ = std::io::Write::write_all(&mut stream, head.as_bytes());
            let _ = stream.set_read_timeout(Some(std::time::Duration::from_secs(10)));
            /* End of stream (or a reset) means the client let the connection go. */
            let released = match stream.read(&mut buf) {
                Ok(0) => true,
                Err(e) => !matches!(
                    e.kind(),
                    std::io::ErrorKind::WouldBlock | std::io::ErrorKind::TimedOut
                ),
                Ok(_) => false,
            };
            let _ = released_tx.send(released);
        }
    });

    thread::sleep(std::time::Duration::from_millis(50));
    (format!("http://{}", addr), released_rx)
}

/// transport064: the response of a refused redirect is released, so its connection closes.
/// The wait blocks its thread, so the test runs on a multi-thread runtime that keeps driving
/// the connection task meanwhile.
#[tokio::test(flavor = "multi_thread")]
async fn test_bhv_transport_064_the_intermediate_response_of_a_refused_redirect_is_released() {
    let (base_url, released) = start_unfinished_redirect_server();
    let transport = TransportOptionsBuilder::new()
        .follow_redirects(true)
        .build()
        .expect("valid transport options");
    let client = DefaultApiClient::new(Some(transport));

    let result = client
        .send_request("GET", &format!("{}/start", base_url), &HashMap::new(), None)
        .await;

    assert!(
        result.is_err(),
        "a redirect to a non-HTTP URL must be refused"
    );
    assert!(
        released
            .recv_timeout(std::time::Duration::from_secs(10))
            .expect("the server must see the connection end"),
        "the refused redirect's response must be released"
    );
}

