/// Starts a server that answers one connection with `response` verbatim and
/// returns its base URL.
fn start_canned_response_server(response: Vec<u8>) -> String {
    let listener = TcpListener::bind("127.0.0.1:0").expect("failed to bind");
    let addr = listener.local_addr().expect("local addr");
    thread::spawn(move || {
        if let Some(Ok(mut stream)) = listener.incoming().next() {
            let mut buf = [0u8; 4096];
            let _ = stream.read(&mut buf);
            let _ = std::io::Write::write_all(&mut stream, &response);
        }
    });
    thread::sleep(std::time::Duration::from_millis(50));
    format!("http://{}", addr)
}

/// A redirect to a non-HTTP scheme is refused: the redirect response arrived,
/// so the error is an `ApiError` with its real status, never a `NetworkError`.
#[tokio::test]
async fn test_bhv_langrust_037_redirect_to_non_http_scheme_is_api_error_with_status() {
    let response = b"HTTP/1.1 302 Found\r\nLocation: ftp://example.com/file\r\nContent-Length: 0\r\nConnection: close\r\n\r\n".to_vec();
    let base_url = start_canned_response_server(response);

    let transport = TransportOptionsBuilder::new()
        .follow_redirects(true)
        .build()
        .expect("valid transport options");
    let client = DefaultApiClient::new(Some(transport));
    let err = client
        .send_request("GET", &format!("{}/start", base_url), &HashMap::new(), None)
        .await
        .expect_err("a redirect to ftp:// must be refused");
    assert!(
        err.downcast_ref::<NetworkError>().is_none(),
        "must not be a NetworkError: {}",
        err
    );
    let api_err = err
        .downcast_ref::<ApiError>()
        .unwrap_or_else(|| panic!("expected ApiError, got: {}", err));
    assert_eq!(api_err.status_code(), 302);
}

/// ca-cert-fail-fast: an explicitly configured CA certificate path that cannot
/// be read or parsed must fail fast at construction rather than silently
/// falling back to the system trust store (security theater). The builder
/// returns `ConfigurationError::InvalidCaCertificate`: a configuration
/// mistake, not an `ApiError`, and not a panic.
#[test]
fn test_bhv_errors_041_nonexistent_ca_cert_path_fails_fast() {
    let result = TransportOptionsBuilder::new()
        .ca_cert_path("/nonexistent/ca.pem")
        .build();
    assert!(
        matches!(result, Err(ConfigurationError::InvalidCaCertificate(_))),
        "expected InvalidCaCertificate, got {:?}",
        result
    );
    /* ConfigurationError deliberately does not implement the SDK root trait:
     * `let _: &dyn OpenAPIError = &ConfigurationError::...` would not compile. */
}

// The per-part MIME sniffing (Gap J), multipart filename-directive (Gap BI /
// Gap F), response charset-decoding (Gap H), and spec-declared API-key
// sensitive-header (Gap 3.1) unit tests were moved in-crate (see
// `src/default_api_client.rs`'s `#[cfg(test)] mod tests`) because the helpers
// they exercise (mime_for_filename, build_filename_directive,
// validate_multipart_filename, decode_text_body, parse_charset,
// SENSITIVE_HEADER_NAMES) live in the crate-private `default_api_client` module.

/// Sends `requests` calls through a client that injects X-Request-ID and returns
/// the ids the server received, in arrival order.
async fn captured_request_ids(requests: usize) -> Vec<String> {
    let (base_url, captured) = start_request_id_capture_server(requests);
    let transport = TransportOptionsBuilder::new()
        .inject_request_id(true)
        .build()
        .expect("valid transport options");
    let client = DefaultApiClient::new(Some(transport));

    for _ in 0..requests {
        client
            .send_request("GET", &format!("{}/test", base_url), &HashMap::new(), None)
            .await
            .expect("unexpected error");
    }
    let ids = captured.lock().unwrap().clone();
    ids
}

/// Each call gets a request id of its own, so two calls never share one.
#[tokio::test]
async fn test_bhv_transport_007_generates_unique_request_ids() {
    let ids = captured_request_ids(2).await;

    assert_eq!(2, ids.len(), "{:?}", ids);
    assert_ne!(ids[0], ids[1]);
}

/// Every request of a run carries a fresh X-Request-ID, one distinct value per call.
#[tokio::test]
async fn test_bhv_transport_008_generates_a_unique_x_request_id_per_request() {
    let ids = captured_request_ids(3).await;
    let distinct: std::collections::HashSet<&String> = ids.iter().collect();

    assert_eq!(3, ids.len(), "{:?}", ids);
    assert_eq!(3, distinct.len(), "{:?}", ids);
}

/// The injected X-Request-ID is a UUID in its canonical lower-case hyphenated form.
#[tokio::test]
async fn test_bhv_transport_014_injects_x_request_id_with_uuid_format() {
    let ids = captured_request_ids(1).await;

    assert_eq!(1, ids.len(), "{:?}", ids);
    let parsed = uuid::Uuid::parse_str(&ids[0]).expect("the request id is a UUID");
    assert_eq!(parsed.to_string(), ids[0]);
}

