/// redirects052: a redirect to a different origin removes Authorization, Cookie, Proxy-Authorization and every custom secret-named header.
#[tokio::test]
async fn test_bhv_redirects_052_a_cross_origin_redirect_removes_every_credential_header() {
    let (origin_url, dest_captured) = start_cross_origin_redirect_servers();

    let transport = TransportOptionsBuilder::new()
        .follow_redirects(true)
        .build()
        .expect("valid transport options");
    let client = DefaultApiClient::new(Some(transport));

    let mut headers = HashMap::new();
    headers.insert("Authorization".to_string(), "Bearer secret".to_string());
    headers.insert("Cookie".to_string(), "session=abc".to_string());
    headers.insert(
        "Proxy-Authorization".to_string(),
        "Basic c2VjcmV0".to_string(),
    );
    headers.insert("X-Access-Token".to_string(), "token-value".to_string());
    headers.insert("X-Trace".to_string(), "keep".to_string());

    let _ = client
        .send_request("GET", &format!("{}/start", origin_url), &headers, None)
        .await;

    let calls = dest_captured.lock().unwrap();
    assert_eq!(
        1,
        calls.len(),
        "the cross-origin destination must have received the follow-up"
    );
    let followup = calls[0].to_lowercase();
    for stripped in [
        "authorization:",
        "cookie:",
        "proxy-authorization:",
        "x-access-token:",
    ] {
        assert!(
            !followup.contains(stripped),
            "{} must be stripped on a cross-origin redirect: {}",
            stripped,
            calls[0]
        );
    }
    assert!(
        followup.contains("x-trace:"),
        "non-sensitive X-Trace must survive: {}",
        calls[0]
    );
}

