/// Binds a loopback listener for a scripted test server and returns its base URL.
fn bind_local_server() -> (TcpListener, String) {
    let listener = TcpListener::bind("127.0.0.1:0").expect("failed to bind");
    let url = format!("http://{}", listener.local_addr().unwrap());
    (listener, url)
}

/// Serves one connection per scripted response, recording each request head.
fn serve_scripted(listener: TcpListener, responses: Vec<String>, log: Arc<Mutex<Vec<String>>>) {
    thread::spawn(move || {
        for response in responses {
            let Ok((mut stream, _)) = listener.accept() else {
                return;
            };
            let mut buf = [0u8; 4096];
            let n_read = stream.read(&mut buf).unwrap_or(0);
            log.lock()
                .unwrap()
                .push(String::from_utf8_lossy(&buf[..n_read]).to_string());
            let _ = std::io::Write::write_all(&mut stream, response.as_bytes());
        }
    });
    thread::sleep(std::time::Duration::from_millis(50));
}

fn redirect_response(location: &str) -> String {
    format!(
        "HTTP/1.1 302 Found\r\nLocation: {}\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
        location
    )
}

fn empty_ok_response() -> String {
    "HTTP/1.1 200 OK\r\nContent-Length: 0\r\nConnection: close\r\n\r\n".to_string()
}

#[tokio::test]
async fn test_bhv_misc_128_a_cross_origin_redirect_never_removes_the_proxy_credential() {
    let (proxy, proxy_url) = bind_local_server();
    let log = Arc::new(Mutex::new(Vec::new()));
    serve_scripted(
        proxy,
        vec![
            redirect_response("http://other.example.com/hop"),
            empty_ok_response(),
        ],
        log.clone(),
    );
    let addr = proxy_url.trim_start_matches("http://").to_string();
    let transport = TransportOptionsBuilder::new()
        .proxy(&format!("http://user:pass@{}", addr))
        .follow_redirects(true)
        .build()
        .expect("valid transport options");
    let client = DefaultApiClient::new(Some(transport));

    client
        .send_request("GET", "http://example.com/start", &HashMap::new(), None)
        .await
        .expect("unexpected error");

    let calls = log.lock().unwrap();
    assert_eq!(
        2,
        calls.len(),
        "the redirect must have been followed through the proxy"
    );
    for head in calls.iter() {
        assert!(
            head_header(head, "proxy-authorization").is_some(),
            "{}",
            head
        );
    }
}

#[tokio::test]
async fn test_bhv_misc_130_a_credential_removed_by_a_cross_origin_hop_is_not_restored_on_return() {
    let (origin, origin_url) = bind_local_server();
    let (other, other_url) = bind_local_server();
    let log = Arc::new(Mutex::new(Vec::new()));
    serve_scripted(
        origin,
        vec![
            redirect_response(&format!("{}/hop", other_url)),
            empty_ok_response(),
        ],
        log.clone(),
    );
    serve_scripted(
        other,
        vec![redirect_response(&format!("{}/back", origin_url))],
        log.clone(),
    );
    let transport = TransportOptionsBuilder::new()
        .follow_redirects(true)
        .build()
        .expect("valid transport options");
    let client = DefaultApiClient::new(Some(transport));
    let mut headers = HashMap::new();
    headers.insert("Authorization".to_string(), "Bearer secret".to_string());

    client
        .send_request("GET", &format!("{}/start", origin_url), &headers, None)
        .await
        .expect("unexpected error");

    let calls = log.lock().unwrap();
    assert_eq!(
        3,
        calls.len(),
        "start, cross-origin hop and return must each be sent"
    );
    assert!(
        head_header(&calls[0], "authorization").is_some(),
        "{}",
        calls[0]
    );
    assert_eq!(
        None,
        head_header(&calls[1], "authorization"),
        "{}",
        calls[1]
    );
    assert_eq!(
        None,
        head_header(&calls[2], "authorization"),
        "{}",
        calls[2]
    );
}

