fn service_unavailable_response(retry_after: &str) -> String {
    let retry = if retry_after.is_empty() {
        String::new()
    } else {
        format!("Retry-After: {}\r\n", retry_after)
    };
    format!(
        "HTTP/1.1 503 Service Unavailable\r\n{}Content-Length: 0\r\nConnection: close\r\n\r\n",
        retry
    )
}

